entages of amounts, percentage change, reversing VAT and discounts, successive changes and compound interest.","sector_style":"Banking & Finance","time_limit_seconds":750,"existing":false},{"type_slug":"numerical-reasoning","slug":"ratios-and-rates","name":"Numerical Reasoning: Ratios, Averages & Rates","description":"Sharing in a ratio, missing averages, rates of work, currency conversion and average speed.","sector_style":"Logistics & Operations","time_limit_seconds":750,"existing":false},{"type_slug":"numerical-reasoning","slug":"charts-and-tables","name":"Numerical Reasoning: Charts & Tables","description":"Read a bar chart or a table and work out totals, shares, changes and margins.","sector_style":"Accounting & Audit","time_limit_seconds":900,"existing":false},{"type_slug":"verbal-reasoning","slug":"business-briefings","name":"Verbal Reasoning: Business Briefings","description":"True, False or Cannot Say from short business and funding passages.","sector_style":"Retail & Consumer","time_limit_seconds":600,"existing":false},{"type_slug":"verbal-reasoning","slug":"science-and-society","name":"Verbal Reasoning: Science & Society","description":"True, False or Cannot Say from short passages on research, transport and energy.","sector_style":"Public Sector","time_limit_seconds":600,"existing":false},{"type_slug":"diagrammatic-reasoning","slug":"shape-transformations","name":"Diagrammatic Reasoning: Shape Transformations","description":"Shading cycles, rotations and layered shapes — sometimes two rules at once.","sector_style":"Technology","time_limit_seconds":450,"existing":false},{"type_slug":"diagrammatic-reasoning","slug":"movement-patterns","name":"Diagrammatic Reasoning: Movement & Counting","description":"Shapes that move around a frame, and counts and sizes that change step by step.","sector_style":"Engineering","time_limit_seconds":450,"existing":false},{"type_slug":"diagrammatic-reasoning","slug":"matrices-and-odd-one-out","name":"Diagrammatic Reasoning: Matrices & Odd One Out","description":"Complete a 3 × 3 grid, or find the figure that breaks the rule.","sector_style":"Technology","time_limit_seconds":600,"existing":false},{"type_slug":"critical-thinking","slug":"assessing-inferences","name":null,"description":null,"sector_style":null,"time_limit_seconds":660,"existing":true},{"type_slug":"situational-judgement","slug":"graduate-programme-scenarios","name":null,"description":null,"sector_style":null,"time_limit_seconds":660,"existing":true},{"type_slug":"numerical-reasoning","slug":"data-interpretation","name":null,"description":null,"sector_style":null,"time_limit_seconds":900,"existing":true},{"type_slug":"verbal-reasoning","slug":"passage-analysis","name":null,"description":null,"sector_style":null,"time_limit_seconds":825,"existing":true},{"type_slug":"diagrammatic-reasoning","slug":"sequences-and-patterns","name":null,"description":null,"sector_style":null,"time_limit_seconds":360,"existing":true}]$packs$::jsonb)
    as b(type_slug text, slug text, name text, description text, sector_style text, time_limit_seconds integer, existing boolean)
